-- Direct join AVG for scan_quality
SELECT ROUND(AVG(
    POWER(10.0 / (LOG10(CAST(p.cloud_metrics->>'Scan_Resol_Mm' AS numeric) * 1000) / LOG10(CAST(p.cloud_metrics->>'Point_Dense' AS numeric)) * 5), 1.5) * 
    (CAST(p.cloud_metrics->>'Cover_Pct' AS numeric) * (1 + CAST(p.cloud_metrics->>'Lap_Pct' AS numeric)/100 * (1 - CAST(p.cloud_metrics->>'Cover_Pct' AS numeric)/100)) / 100) * 
    POWER(1 - CAST(p.cloud_metrics->>'Noise_Db' AS numeric) / 30.0, 2)
), 4) as sq_avg FROM scans s JOIN pointcloud p ON s.arcref = p.arcref AND s.crewref = p.crewref WHERE s.zoneref = 'SC1017';

-- CTE approach AVG for scan_quality  
SELECT ROUND(AVG(sqs), 4) as sq_avg FROM (
    SELECT POWER(10.0 / (LOG10(CAST(p.cloud_metrics->>'Scan_Resol_Mm' AS numeric) * 1000) / LOG10(CAST(p.cloud_metrics->>'Point_Dense' AS numeric)) * 5), 1.5) * 
    (CAST(p.cloud_metrics->>'Cover_Pct' AS numeric) * (1 + CAST(p.cloud_metrics->>'Lap_Pct' AS numeric)/100 * (1 - CAST(p.cloud_metrics->>'Cover_Pct' AS numeric)/100)) / 100) * 
    POWER(1 - CAST(p.cloud_metrics->>'Noise_Db' AS numeric) / 30.0, 2) as sqs
    FROM scans s JOIN pointcloud p ON s.arcref = p.arcref AND s.crewref = p.crewref WHERE s.zoneref = 'SC1017'
) sub;

SELECT COUNT(*) FROM (
    SELECT s.questregistry 
    FROM scans s 
    JOIN pointcloud p ON s.arcref = p.arcref AND s.crewref = p.crewref
    JOIN environment e ON s.zoneref = e.zoneref
) sub;
